package cloud.treenewbee.quizforge.hub.admin;

import java.sql.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import tools.jackson.databind.json.JsonMapper;
import cloud.treenewbee.quizforge.hub.account.*;
import cloud.treenewbee.quizforge.hub.common.HubException;
import cloud.treenewbee.quizforge.hub.storage.HubDatabase;
import static cloud.treenewbee.quizforge.hub.storage.HubDatabase.*;
import static cloud.treenewbee.quizforge.hub.admin.AdminAccess.*;

@Service
public class AdminService {
    private final HubDatabase db;private final PracticeAdminClient bridge;private final AuthPolicy policy;
    private final JsonMapper json=JsonMapper.builder().build();private static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");
    public AdminService(HubDatabase db,PracticeAdminClient bridge,AuthPolicy policy){this.db=db;this.bridge=bridge;this.policy=policy;db.transaction(c->{update(c,"INSERT OR IGNORE INTO admin_meta VALUES('metrics-start',?)",String.valueOf(System.currentTimeMillis()));return null;});}
    public Map<String,Object> contact(){return db.read(c->row(c,"SELECT content,revision FROM admin_contact WHERE id=1"));}
    public Object contact(Map<String,Object> input,Object actor){
        if(input.keySet().stream().anyMatch(k->!Set.of("content","revision").contains(k))||!(input.get("content") instanceof String raw)||raw.length()>4000||raw.chars().anyMatch(ch->ch<32&&ch!=9&&ch!=10&&ch!=13||ch==127))throw new HubException(400,"联系方式须为最多 4000 字的纯文本");
        String content=raw.replace("\r\n","\n").replace("\r","\n").strip();
        return db.transaction(c->{current(c,actor);var previous=row(c,"SELECT content,revision FROM admin_contact WHERE id=1");long expected=integer(input.get("revision"),0,9007199254740991L,"请重新读取联系方式再保存");if(expected!=number(previous.get("revision")))throw new HubException(409,"联系方式已被更新，请重新读取");
            if(!content.equals(previous.get("content"))){update(c,"UPDATE admin_contact SET content=?,revision=revision+1 WHERE id=1",content);AdminAccess.audit(c,actor,"admin-contact-updated","admin-contact",Map.of("previous",previous,"replacement",row(c,"SELECT content,revision FROM admin_contact WHERE id=1")));}return row(c,"SELECT content,revision FROM admin_contact WHERE id=1");});
    }
    public Object invitations(){return db.read(c->{var items=rows(c,"SELECT i.id,i.prefix,i.created,i.expires,i.revoked,i.used,i.user_id,COALESCE(u.email,u.name) AS used_by FROM invitations i LEFT JOIN users u ON u.id=i.user_id ORDER BY i.created DESC,i.id LIMIT 1000");long now=System.currentTimeMillis();for(var i:items)i.put("state",i.get("used")!=null?"used":i.get("revoked")!=null?"revoked":number(i.get("expires"))<=now?"expired":"available");return Map.of("items",items,"invitationRequired",policy.get(c).get("invitationRequired"));});}
    public Object createInvitations(Map<String,Object> input,Object actor){
        if(input.keySet().stream().anyMatch(k->!Set.of("count","days").contains(k)))throw new HubException(400,"邀请码字段无效");long count=integer(input.getOrDefault("count",1),1,100,"每次生成 1–100 个邀请码"),days=integer(input.getOrDefault("days",30),1,365,"有效期须为 1–365 天");
        return db.transaction(c->{current(c,actor);var issued=new ArrayList<Map<String,Object>>();long now=System.currentTimeMillis(),expires=now+days*86400000;
            for(int i=0;i<count;i++){String body=AccountCrypto.token().substring(0,32).toUpperCase(Locale.ROOT),code="QF-"+String.join("-",body.substring(0,8),body.substring(8,16),body.substring(16,24),body.substring(24)),id=UUID.randomUUID().toString();update(c,"INSERT INTO invitations(id,digest,prefix,created_by,created,expires) VALUES(?,?,?,?,?,?)",id,AccountCrypto.sha(code),code.substring(0,11),actor,now,expires);update(c,"INSERT INTO invitation_audit VALUES(?,?,?,?,?)",UUID.randomUUID().toString(),id,actor,"create",now);issued.add(Map.of("id",id,"code",code,"expires",expires));}return Map.of("items",issued);});
    }
    public Object revokeInvitation(String id,Object actor){return db.transaction(c->{current(c,actor);var invite=row(c,"SELECT used,revoked FROM invitations WHERE id=?",id);if(invite==null)throw new HubException(404,"邀请码不存在");if(invite.get("used")!=null)throw new HubException(409,"邀请码已使用，不能撤回账号");if(invite.get("revoked")==null){long now=System.currentTimeMillis();update(c,"UPDATE invitations SET revoked=? WHERE id=?",now,id);update(c,"INSERT INTO invitation_audit VALUES(?,?,?,?,?)",UUID.randomUUID().toString(),id,actor,"revoke",now);}return Map.of("ok",true);});}
    public Object profile(String id){return db.read(c->{var u=row(c,"SELECT created FROM users WHERE id=? AND NOT EXISTS(SELECT 1 FROM user_blocks WHERE user_id=users.id)",id);if(u==null)throw new HubException(404,"用户不存在或已被封禁");var profile=AccountStore.profile(c,id);profile.put("created",u.get("created"));return Map.of("user",profile);});}
    public Object block(String id,Map<String,Object> input,Object actor){
        String note=reason(input);if(id.equals(actor)||!(input.get("blocked") instanceof Boolean blocked))throw new HubException(400,"不能封禁当前管理员，且必须明确账户状态");
        return db.transaction(c->{current(c,actor);if(row(c,"SELECT 1 FROM users WHERE id=?",id)==null)throw new HubException(404,"用户不存在");if(blocked){update(c,"INSERT INTO user_blocks VALUES(?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET actor_id=excluded.actor_id,reason=excluded.reason,created=excluded.created",id,actor,note,System.currentTimeMillis());update(c,"DELETE FROM sessions WHERE user_id=?",id);update(c,"UPDATE connect_devices SET revoked=1 WHERE user_id=?",id);update(c,"DELETE FROM connect_codes WHERE user_id=?",id);}else update(c,"DELETE FROM user_blocks WHERE user_id=?",id);AdminAccess.audit(c,actor,blocked?"user-blocked":"user-unblocked",id,Map.of("reason",note));return Map.of("ok",true);});
    }
    public Object users(String query,int page,String token){
        var result=db.read(c->{String q=query.substring(0,Math.min(query.length(),100)),term="%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%",where=" WHERE name LIKE ? ESCAPE '!' OR email LIKE ? ESCAPE '!' OR id IN(SELECT user_id FROM user_phones WHERE phone LIKE ? ESCAPE '!')";
            var users=rows(c,"SELECT id,name,email,(SELECT phone FROM user_phones WHERE user_id=users.id) AS phone,admin,created FROM users"+where+" ORDER BY created DESC,id LIMIT 50 OFFSET ?",term,term,term,(page-1)*50);
            for(var u:users){Object id=u.get("id");u.put("disabled",row(c,"SELECT 1 FROM user_blocks WHERE user_id=?",id)!=null);var seen=row(c,"SELECT last_seen FROM activity_online WHERE user_id=?",id);u.put("lastSeen",seen==null?null:seen.get("last_seen"));var invite=row(c,"SELECT prefix FROM invitations WHERE user_id=?",id);u.put("invitation",invite==null?null:invite.get("prefix"));var ai=row(c,"SELECT balance FROM ai_points WHERE user_id=?",id);u.put("ai",Map.of("balance",ai==null?0:ai.get("balance"),"redeemed",number(row(c,"SELECT COALESCE(SUM(delta),0) n FROM ai_points_ledger WHERE user_id=? AND kind='redeem'",id).get("n"))));}
            var map=new LinkedHashMap<String,Object>();map.put("users",users);map.put("page",page);map.put("count",number(row(c,"SELECT COUNT(*) n FROM users"+where,term,term,term).get("n")));return map;});
        var users=(List<Map<String,Object>>)result.get("users");
        if(bridge.enabled()&&!users.isEmpty()){String ids=String.join(",",users.stream().map(u->u.get("id").toString()).toList());var quotas=bridge.call("/accounts?ids="+ids,token);var accounts=(Map<?,?>)quotas.get("accounts");result.put("defaults",quotas.get("defaults"));for(var u:users)u.put("resources",accounts.get(u.get("id")));}
        else{result.put("defaults",null);for(var u:users)u.put("resources",null);}
        return result;
    }
    public Object activity(Object id,String kind){if(!Set.of("visit","practice","heartbeat").contains(kind))throw new HubException(400,"活动类型无效");return db.transaction(c->{if(AccountStore.blocked(c,id))throw new HubException(401,"账号已停用");long now=System.currentTimeMillis();update(c,"INSERT INTO activity_online VALUES(?,?) ON CONFLICT(user_id) DO UPDATE SET last_seen=excluded.last_seen",id,now);if(!kind.equals("heartbeat"))update(c,"INSERT INTO activity_daily VALUES(?,?,?) ON CONFLICT(day,user_id) DO UPDATE SET practiced=MAX(practiced,excluded.practiced)",LocalDate.now(ZONE).toString(),id,kind.equals("practice")?1:0);return Map.of("ok",true);});}
    public Object overview(int days,String token){var result=db.read(c->{int n=days==30?30:7;LocalDate today=LocalDate.now(ZONE);var trend=new ArrayList<Map<String,Object>>();for(int i=n-1;i>=0;i--){LocalDate day=today.minusDays(i);var point=row(c,"SELECT COUNT(*) active,COALESCE(SUM(practiced),0) practice FROM activity_daily WHERE day=?",day.toString());point.put("day",day.toString());point.put("registered",number(row(c,"SELECT COUNT(*) n FROM users WHERE created>=? AND created<?",day.atStartOfDay(ZONE).toInstant().toString(),day.plusDays(1).atStartOfDay(ZONE).toInstant().toString()).get("n")));trend.add(point);}var m=new LinkedHashMap<String,Object>();m.put("total",number(row(c,"SELECT COUNT(*) n FROM users").get("n")));m.put("online",number(row(c,"SELECT COUNT(*) n FROM activity_online o WHERE last_seen>? AND NOT EXISTS(SELECT 1 FROM user_blocks WHERE user_id=o.user_id)",System.currentTimeMillis()-300000).get("n")));m.put("today",trend.getLast());m.put("trend",trend);var transfers=row(c,"SELECT requests,bytes FROM activity_transfers WHERE day=?",today.toString());m.put("transfers",transfers==null?Map.of("requests",0,"bytes",0):transfers);m.put("pendingPacks",number(row(c,"SELECT COUNT(*) n FROM packs WHERE status='pending'").get("n")));m.put("reportingSince",Long.parseLong(row(c,"SELECT value FROM admin_meta WHERE key='metrics-start'").get("value").toString()));m.put("timezone","Asia/Shanghai");m.put("onlineWindowSeconds",300);return m;});
        if(bridge.enabled()){var remote=bridge.call("/summary",token);result.put("cloud",remote);var local=(Map<?,?>)result.get("transfers");var transfers=(Map<?,?>)remote.get("transfers");result.put("transfers",Map.of("requests",number(local.get("requests"))+number(transfers.get("requests")),"bytes",number(local.get("bytes"))+number(transfers.get("bytes"))));}else result.put("cloud",null);return result;}
    public Object reports(){return db.read(c->Map.of("items",rows(c,"SELECT r.id,r.pack_id,r.reason,r.created,p.title,u.name AS reporter FROM reports r JOIN packs p ON p.id=r.pack_id JOIN users u ON u.id=r.user_id ORDER BY r.created DESC LIMIT 100")));}
    public Object audit(String token){var items=db.read(c->{var local=rows(c,"SELECT a.*,u.name AS actor FROM admin_audit a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created DESC LIMIT 100");for(var item:local)item.put("detail",json.readValue(item.get("detail").toString(),Object.class));var invites=rows(c,"SELECT a.id,a.actor_id,a.invitation_id AS target,'invitation-'||a.action AS action,a.created,i.prefix,u.name AS actor FROM invitation_audit a JOIN invitations i ON i.id=a.invitation_id LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created DESC LIMIT 100");for(var invite:invites){invite.put("detail",Map.of("prefix",invite.remove("prefix")));local.add(invite);}return local;});
        if(bridge.enabled()){var remote=bridge.call("/audit",token);for(var raw:(List<?>)remote.get("entries")){var item=new LinkedHashMap<String,Object>((Map<String,Object>)raw);var detail=new LinkedHashMap<String,Object>();for(String key:List.of("previous","replacement","reason"))detail.put(key,item.get(key));item.put("detail",detail);item.put("target",item.getOrDefault("user_id",""));item.put("actor",db.read(c->{var row=row(c,"SELECT name FROM users WHERE id=?",item.get("actor_id"));return row==null?"系统":row.get("name");}));items.add(item);}}
        items.sort((a,b)->Long.compare(number(b.get("created")),number(a.get("created"))));return Map.of("items",items.stream().limit(150).toList());}
}
